// loft: a slot (lines from (-10, 5) to (10, 5) and (10, -5) to (-10, -5), half circles round (15, 0) and (-15, 0)) at z = 0 to a circle of radius 10 at z = 20, the end of the slot at (15, 0) connected to the circle's start
export function c010(context is Context, id is Id)
{
    const p0 = newSketchOnPlane(context, id + "p0", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skLineSegment(p0, "line1", { "start" : vector(-10, 5) * millimeter, "end" : vector(10, 5) * millimeter });
    skArc(p0, "arc1", { "start" : vector(10, 5) * millimeter, "mid" : vector(15, 0) * millimeter, "end" : vector(10, -5) * millimeter });
    skLineSegment(p0, "line2", { "start" : vector(10, -5) * millimeter, "end" : vector(-10, -5) * millimeter });
    skArc(p0, "arc2", { "start" : vector(-10, -5) * millimeter, "mid" : vector(-15, 0) * millimeter, "end" : vector(-10, 5) * millimeter });
    skSolve(p0);
    const p1 = newSketchOnPlane(context, id + "p1", { "sketchPlane" : plane(vector(0, 0, 20) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(p1, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 10 * millimeter });
    skSolve(p1);
    loft(context, id + "loft1", { "sheetProfilesArray" : [{ "sheetProfileEntities" : qSketchRegion(id + "p0") }, { "sheetProfileEntities" : qSketchRegion(id + "p1") }], "bodyType" : ExtendedToolBodyType.SOLID, "operationType" : NewBodyOperationType.NEW, "startCondition" : LoftEndDerivativeType.DEFAULT, "endCondition" : LoftEndDerivativeType.DEFAULT, "matchConnections" : true, "connections" : [{ "connectionEntities" : qUnion([qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "p0", EntityType.BODY), BodyType.SHEET), EntityType.EDGE), vector(15, 0, 0) * millimeter), qOwnedByBody(qBodyType(qCreatedBy(id + "p1", EntityType.BODY), BodyType.SHEET), EntityType.EDGE)]), "connectionEdgeQueries" : qUnion([qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "p0", EntityType.BODY), BodyType.SHEET), EntityType.EDGE), vector(15, 0, 0) * millimeter), qOwnedByBody(qBodyType(qCreatedBy(id + "p1", EntityType.BODY), BodyType.SHEET), EntityType.EDGE)]), "connectionEdgeParameters" : [0.5, 0] }] });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "loft1", EntityType.BODY), BodyType.SOLID)), "volume" : roundToPrecision(evVolume(context, { "entities" : qBodyType(qCreatedBy(id + "loft1", EntityType.BODY), BodyType.SOLID) }) / millimeter ^ 3, 6) };
